// === Tab: mySketch ===
// Click and drag the mouse to view the scene from different angles.

let particles;

function setup() {
  createCanvas(920, 690, WEBGL);
	colorMode(HSB)
  strokeWeight(3);
  // Create a new p5.Geometry object with random spheres.
  particles = buildGeometry(createParticles);

  describe('Ten colored spheres placed randomly against a gray background. A box encloses the spheres.');
}

function draw() {
  background(50);

  // Enable orbiting with the mouse.
  orbitControl();
	rotateY(frameCount*.01);
	scale(2);
  // Turn on the lights.
  lights();
  ambientLight(20);
	directionalLight(100, 0, 100, 1, 1, 0);
  // Style the particles.
  noStroke();
  fill(255);

  // Draw the particles.
  model(particles);

  // Calculate the bounding box.
  let bbox = particles.calculateBoundingBox();

  // Translate to the bounding box's center.
  translate(bbox.offset.x, bbox.offset.y, bbox.offset.z);

  // Style the bounding box.
  stroke(255);
  noFill();

  // Draw the bounding box.
  box(bbox.size.x, bbox.size.y, bbox.size.z);
}

function createParticles() {
  for (let i = 0; i < 100; i += 1) {
    // Calculate random coordinates.
    let x = randomGaussian(0, height/20);
    let y = randomGaussian(0, height/20);
    let z = randomGaussian(0, height/20);

    push();
    // Translate to the particle's coordinates.
    translate(x, y, z);
		// Set the color
		fill(random(360), 80, 100);
    // Draw the particle.
    sphere(6);
    pop();
  }
}

